// Validate the form submission and compute a transparent rule-based score.
const cfg = $('Config').first().json;
const body = $('Lead Webhook').first().json.body || {};
const s = v => (v === undefined || v === null) ? '' : String(v).trim();

const lead = {
  received_at: new Date().toISOString(),
  name: s(body.name).slice(0, 200),
  email: s(body.email).toLowerCase().slice(0, 200),
  company: s(body.company).slice(0, 200),
  company_size: s(body.company_size).slice(0, 50),
  budget: s(body.budget).slice(0, 50),
  timeline: s(body.timeline).slice(0, 100),
  message: s(body.message).slice(0, 2000),
  source: s(body.source).slice(0, 100) || 'web-form',
};

const errors = [];
if (!lead.name) errors.push('name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) errors.push('a valid email is required');
if (!lead.message) errors.push('message is required');

// Parse "5000", "$5,000", "5k" -> 5000
const parseMoney = t => {
  const clean = t.replace(/,/g, '');
  const k = clean.match(/(\d+(?:\.\d+)?)\s*k\b/i);
  if (k) return Number(k[1]) * 1000;
  const n = clean.match(/\d+(?:\.\d+)?/);
  return n ? Number(n[0]) : 0;
};
const firstInt = t => { const m = t.match(/\d+/); return m ? Number(m[0]) : 0; };

const freeDomains = ['gmail.com','googlemail.com','yahoo.com','hotmail.com','outlook.com','live.com','icloud.com','aol.com','proton.me','protonmail.com','rediffmail.com','gmx.com'];
const domain = lead.email.split('@')[1] || '';

let rule = 0;
const reasons = [];
if (domain && !freeDomains.includes(domain)) { rule += 25; reasons.push('business email domain'); }

const budget = parseMoney(lead.budget);
if (budget >= cfg.budget_high) { rule += 35; reasons.push(`budget >= ${cfg.budget_high}`); }
else if (budget >= cfg.budget_mid) { rule += 20; reasons.push(`budget >= ${cfg.budget_mid}`); }

const size = firstInt(lead.company_size);
if (size >= 50) { rule += 20; reasons.push('50+ employees'); }
else if (size >= 10) { rule += 10; reasons.push('10+ employees'); }

if (/asap|urgent|immediately|this week|this month/i.test(lead.timeline)) { rule += 20; reasons.push('urgent timeline'); }
else if (/next month|1-3 months|this quarter|next quarter/i.test(lead.timeline)) { rule += 10; reasons.push('near-term timeline'); }

return [{ json: { ...lead, budget_value: budget, valid: errors.length === 0, errors, rule_score: Math.min(rule, 100), rule_reasons: reasons } }];

