// Combine the rule score with the AI score. If the AI call failed, fall back to rules only.
const cfg = $('Config').first().json;
const lead = $('Normalize & Pre-score').first().json;
const res = $input.first().json;

let ai = null;
let ai_error = null;
try {
  const content = res.choices?.[0]?.message?.content;
  if (!content) throw new Error(res.error?.message || 'no AI response');
  ai = JSON.parse(content);
} catch (e) {
  ai_error = String(e.message || e).slice(0, 300);
}

const raw = ai ? Number(ai.intent_score) : NaN;
const aiScore = Number.isFinite(raw) ? Math.max(0, Math.min(100, Math.round(raw))) : null;
const allowed = ['sales', 'support', 'partnership', 'spam', 'other'];
const category = ai && allowed.includes(ai.category) ? ai.category : null;

let final, method;
if (category === 'spam') { final = 0; method = 'ai-flagged-spam'; }
else if (aiScore !== null) { final = Math.round(cfg.rule_weight * lead.rule_score + (1 - cfg.rule_weight) * aiScore); method = 'blended'; }
else { final = lead.rule_score; method = 'rules-only'; }

const tier = final >= cfg.hot_threshold ? 'hot' : final >= cfg.warm_threshold ? 'warm' : 'cold';

const out = {
  lead_id: `L-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
  received_at: lead.received_at,
  name: lead.name,
  email: lead.email,
  company: lead.company,
  company_size: lead.company_size,
  budget: lead.budget,
  timeline: lead.timeline,
  source: lead.source,
  message: lead.message,
  rule_score: lead.rule_score,
  rule_reasons: lead.rule_reasons.join('; '),
  ai_score: aiScore,
  ai_category: category,
  ai_summary: ai ? String(ai.summary || '').slice(0, 300) : null,
  ai_next_step: ai ? String(ai.next_step || '').slice(0, 300) : null,
  ai_error,
  final_score: final,
  scoring_method: method,
  tier,
};
return [{ json: out }];

